import { useEffect, useState, useCallback } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  ClipboardList, Plus, Search, RefreshCw,
  Clock, User, Trash2, ShieldAlert, Activity,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";

type Severity = "critical" | "high" | "medium" | "low";
type Status   = "open" | "investigating" | "contained" | "resolved" | "closed";

interface Incident {
  id:          string;
  title:       string;
  description: string;
  severity:    Severity;
  status:      Status;
  category:    string;
  assignee?:   string;
  tags:        string[];
  iocs?:       string[];
  created_at:  string;
  updated_at:  string;
}

const CATEGORIES = ["Malware","Ransomware","Phishing","Data Breach","DDoS","Insider Threat","APT","Vulnerability Exploit","Other"];

const SEVERITY_COLORS: Record<Severity, string> = {
  critical: "bg-destructive/15 text-destructive border-destructive/40",
  high:     "bg-orange-500/15 text-orange-400 border-orange-500/40",
  medium:   "bg-yellow-500/15 text-yellow-500 border-yellow-500/40",
  low:      "bg-green-500/15 text-green-500 border-green-500/40",
};

const STATUS_COLORS: Record<Status, string> = {
  open:          "bg-destructive/15 text-destructive border-destructive/40",
  investigating: "bg-orange-500/15 text-orange-400 border-orange-500/40",
  contained:     "bg-yellow-500/15 text-yellow-500 border-yellow-500/40",
  resolved:      "bg-blue-500/15 text-blue-400 border-blue-500/40",
  closed:        "bg-green-500/15 text-green-500 border-green-500/40",
};

const STATUS_FLOW: Status[] = ["open","investigating","contained","resolved","closed"];

function timeAgo(iso: string) {
  const m = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (m < 1)  return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

function shortId(id: string) {
  return "INC-" + id.slice(0, 6).toUpperCase();
}

interface NewForm {
  title: string; description: string; severity: Severity;
  category: string; tags: string; iocs: string; assignee: string;
}
const EMPTY: NewForm = { title:"", description:"", severity:"medium", category:"Other", tags:"", iocs:"", assignee:"" };

export default function IncidentManager() {
  const { toast } = useToast();
  const [incidents, setIncidents] = useState<Incident[]>([]);
  const [loading, setLoading]     = useState(true);
  const [search, setSearch]       = useState("");
  const [filterStatus, setFilterStatus]     = useState<Status | "all">("all");
  const [filterSeverity, setFilterSeverity] = useState<Severity | "all">("all");
  const [showForm, setShowForm]   = useState(false);
  const [form, setForm]           = useState<NewForm>(EMPTY);
  const [selected, setSelected]   = useState<Incident | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from("cases")
      .select("id,title,description,severity,status,category,assignee,tags,iocs,created_at,updated_at")
      .order("created_at", { ascending: false })
      .limit(200);
    if (error) toast({ title: "Load failed", description: error.message, variant: "destructive" });
    else setIncidents((data ?? []) as unknown as Incident[]);
    setLoading(false);
  }, [toast]);

  useEffect(() => { load(); }, [load]);

  const filtered = incidents.filter(inc => {
    if (filterStatus !== "all" && inc.status !== filterStatus) return false;
    if (filterSeverity !== "all" && inc.severity !== filterSeverity) return false;
    if (search) {
      const s = search.toLowerCase();
      return inc.title.toLowerCase().includes(s)
        || inc.description.toLowerCase().includes(s)
        || (inc.tags ?? []).some(t => t.toLowerCase().includes(s));
    }
    return true;
  });

  const stats = {
    open:          incidents.filter(i => i.status === "open").length,
    investigating: incidents.filter(i => i.status === "investigating").length,
    critical:      incidents.filter(i => i.severity === "critical" && i.status !== "closed").length,
    resolved:      incidents.filter(i => i.status === "resolved" || i.status === "closed").length,
  };

  const createIncident = async () => {
    if (!form.title.trim()) return;
    const row = {
      title:       form.title.trim(),
      description: form.description,
      severity:    form.severity,
      status:      "open" as Status,
      category:    form.category,
      assignee:    form.assignee || null,
      tags:        form.tags.split(",").map(t => t.trim()).filter(Boolean),
      iocs:        form.iocs.split("\n").map(t => t.trim()).filter(Boolean),
    };
    const { data, error } = await supabase.from("cases").insert([row]).select().single();
    if (error) { toast({ title: "Create failed", description: error.message, variant: "destructive" }); return; }
    setIncidents(prev => [data as unknown as Incident, ...prev]);
    setShowForm(false);
    setForm(EMPTY);
    toast({ title: `Incident created: ${shortId(data.id)}` });
  };

  const advanceStatus = async (id: string) => {
    const inc = incidents.find(i => i.id === id);
    if (!inc) return;
    const idx = STATUS_FLOW.indexOf(inc.status);
    if (idx >= STATUS_FLOW.length - 1) return;
    const next = STATUS_FLOW[idx + 1];
    const { error } = await supabase
      .from("cases")
      .update({ status: next, updated_at: new Date().toISOString() })
      .eq("id", id);
    if (error) { toast({ title: "Update failed", description: error.message, variant: "destructive" }); return; }
    setIncidents(prev => prev.map(i => i.id === id ? { ...i, status: next, updated_at: new Date().toISOString() } : i));
    if (selected?.id === id) setSelected(sel => sel ? { ...sel, status: next } : null);
    toast({ title: `Status → ${next}` });
  };

  const deleteIncident = async (id: string) => {
    const { error } = await supabase.from("cases").delete().eq("id", id);
    if (error) { toast({ title: "Delete failed", description: error.message, variant: "destructive" }); return; }
    setIncidents(prev => prev.filter(i => i.id !== id));
    if (selected?.id === id) setSelected(null);
    toast({ title: "Incident deleted" });
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-7xl">
      <div className="mb-6 flex items-start justify-between">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <ClipboardList className="h-6 w-6 text-primary" />
            <h1 className="text-3xl font-bold">Incident Manager</h1>
          </div>
          <p className="text-muted-foreground">Track, triage, and resolve security incidents from detection to closure.</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={load} disabled={loading}>
            <RefreshCw className={`w-4 h-4 ${loading ? "animate-spin" : ""}`} />
          </Button>
          <Button onClick={() => setShowForm(true)} className="gap-2">
            <Plus className="w-4 h-4" />New Incident
          </Button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-3 mb-6">
        {[
          { label: "Open",          value: stats.open,          color: "text-destructive",  bg: "bg-destructive/5 border-destructive/20" },
          { label: "Investigating", value: stats.investigating, color: "text-orange-400",   bg: "bg-orange-500/5 border-orange-500/20" },
          { label: "Active Critical",value: stats.critical,     color: "text-destructive",  bg: "bg-destructive/5 border-destructive/30" },
          { label: "Resolved",      value: stats.resolved,      color: "text-green-500",    bg: "bg-green-500/5 border-green-500/20" },
        ].map(s => (
          <Card key={s.label} className={`border ${s.bg}`}>
            <CardContent className="pt-4 pb-4 text-center">
              <div className={`text-2xl font-bold ${s.color}`}>{s.value}</div>
              <div className="text-xs text-muted-foreground">{s.label}</div>
            </CardContent>
          </Card>
        ))}
      </div>

      <Tabs defaultValue="list">
        <TabsList className="mb-4">
          <TabsTrigger value="list"     className="gap-2"><ClipboardList className="w-4 h-4" />Incidents</TabsTrigger>
          <TabsTrigger value="timeline" className="gap-2"><Activity      className="w-4 h-4" />Timeline</TabsTrigger>
        </TabsList>

        <TabsContent value="list">
          <div className="flex items-center gap-2 mb-4 flex-wrap">
            <div className="relative flex-1 min-w-48">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
              <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search incidents…" className="pl-9 h-9 text-sm" />
            </div>
            <select value={filterStatus} onChange={e => setFilterStatus(e.target.value as Status | "all")}
              className="h-9 rounded-lg border border-border bg-background px-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/40">
              <option value="all">All Status</option>
              {STATUS_FLOW.map(s => <option key={s} value={s}>{s.charAt(0).toUpperCase()+s.slice(1)}</option>)}
            </select>
            <select value={filterSeverity} onChange={e => setFilterSeverity(e.target.value as Severity | "all")}
              className="h-9 rounded-lg border border-border bg-background px-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/40">
              <option value="all">All Severity</option>
              {(["critical","high","medium","low"] as Severity[]).map(s => <option key={s} value={s}>{s.charAt(0).toUpperCase()+s.slice(1)}</option>)}
            </select>
            <span className="text-xs text-muted-foreground ml-auto">{filtered.length} incidents</span>
          </div>

          {loading ? (
            <div className="text-center py-12 text-muted-foreground">Loading incidents…</div>
          ) : filtered.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              <ClipboardList className="w-10 h-10 mx-auto mb-3 opacity-20" />
              <p>No incidents match your filters.</p>
            </div>
          ) : (
            <div className="space-y-2">
              {filtered.map(inc => (
                <Card key={inc.id}
                  className={`border-border/60 bg-card/60 cursor-pointer hover:border-primary/40 transition-all ${selected?.id === inc.id ? "ring-1 ring-primary/40 border-primary/40" : ""} ${inc.severity === "critical" && inc.status !== "closed" ? "border-destructive/30" : ""}`}
                  onClick={() => setSelected(selected?.id === inc.id ? null : inc)}>
                  <CardContent className="py-4 px-5">
                    <div className="flex items-start gap-3">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1 flex-wrap">
                          <span className="text-xs font-mono text-muted-foreground">{shortId(inc.id)}</span>
                          <Badge className={`border text-[10px] ${SEVERITY_COLORS[inc.severity]}`}>{inc.severity.toUpperCase()}</Badge>
                          <Badge className={`border text-[10px] ${STATUS_COLORS[inc.status]}`}>{inc.status}</Badge>
                          <Badge variant="outline" className="text-[10px]">{inc.category}</Badge>
                        </div>
                        <p className="font-medium text-sm mb-1">{inc.title}</p>
                        {selected?.id !== inc.id && (
                          <p className="text-xs text-muted-foreground line-clamp-1">{inc.description}</p>
                        )}
                        {selected?.id === inc.id && (
                          <div className="mt-3 space-y-2">
                            <p className="text-sm text-muted-foreground">{inc.description}</p>
                            {(inc.iocs ?? []).length > 0 && (
                              <div>
                                <p className="text-xs font-medium mb-1">IOCs</p>
                                <div className="flex flex-wrap gap-1">
                                  {inc.iocs!.map(ioc => (
                                    <code key={ioc} className="text-[10px] px-1.5 py-0.5 rounded bg-muted font-mono">{ioc}</code>
                                  ))}
                                </div>
                              </div>
                            )}
                            {(inc.tags ?? []).length > 0 && (
                              <div className="flex flex-wrap gap-1">
                                {inc.tags.map(t => <Badge key={t} variant="secondary" className="text-[9px]">#{t}</Badge>)}
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                      <div className="flex flex-col items-end gap-2 shrink-0">
                        <div className="text-[10px] text-muted-foreground flex items-center gap-1">
                          <Clock className="w-3 h-3" />{timeAgo(inc.created_at)}
                        </div>
                        {inc.assignee && (
                          <div className="text-[10px] text-muted-foreground flex items-center gap-1">
                            <User className="w-3 h-3" />{inc.assignee.split("@")[0]}
                          </div>
                        )}
                        <div className="flex gap-1 mt-1">
                          {inc.status !== "closed" && (
                            <Button size="sm" variant="outline" className="h-6 text-[10px] px-2"
                              onClick={e => { e.stopPropagation(); advanceStatus(inc.id); }}>
                              Advance
                            </Button>
                          )}
                          <Button size="sm" variant="ghost" className="h-6 w-6 p-0 text-muted-foreground hover:text-destructive"
                            onClick={e => { e.stopPropagation(); deleteIncident(inc.id); }}>
                            <Trash2 className="w-3 h-3" />
                          </Button>
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="timeline">
          <div className="relative ml-4">
            <div className="absolute left-0 top-0 bottom-0 w-px bg-border" />
            {[...incidents].sort((a,b) => new Date(b.updated_at).getTime() - new Date(a.updated_at).getTime()).map(inc => (
              <div key={inc.id} className="relative pl-8 pb-6">
                <div className={`absolute left-[-4px] top-1 w-2.5 h-2.5 rounded-full border-2 ${inc.severity === "critical" ? "bg-destructive border-destructive" : inc.severity === "high" ? "bg-orange-400 border-orange-400" : "bg-primary border-primary"}`} />
                <div className="text-[10px] text-muted-foreground mb-1">{new Date(inc.updated_at).toLocaleString()}</div>
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-xs font-mono text-muted-foreground">{shortId(inc.id)}</span>
                  <Badge className={`border text-[9px] ${STATUS_COLORS[inc.status]}`}>{inc.status}</Badge>
                </div>
                <p className="text-sm font-medium">{inc.title}</p>
              </div>
            ))}
          </div>
        </TabsContent>
      </Tabs>

      {/* New Incident Modal */}
      {showForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <Card className="w-full max-w-2xl border-border/60 bg-card shadow-2xl">
            <CardHeader className="border-b border-border/60 pb-4">
              <CardTitle className="flex items-center gap-2">
                <ShieldAlert className="w-5 h-5 text-destructive" />
                Create New Incident
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-5 space-y-4">
              <div>
                <label className="text-xs font-medium text-muted-foreground">Title *</label>
                <Input value={form.title} onChange={e => setForm(f => ({...f, title: e.target.value}))}
                  placeholder="Brief incident description" className="mt-1" />
              </div>
              <div>
                <label className="text-xs font-medium text-muted-foreground">Description</label>
                <textarea value={form.description} onChange={e => setForm(f => ({...f, description: e.target.value}))}
                  placeholder="Detailed description, initial findings, affected systems…"
                  rows={3} className="mt-1 w-full rounded-lg border border-border bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/40" />
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div>
                  <label className="text-xs font-medium text-muted-foreground">Severity</label>
                  <select value={form.severity} onChange={e => setForm(f => ({...f, severity: e.target.value as Severity}))}
                    className="mt-1 w-full h-9 rounded-lg border border-border bg-background px-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/40">
                    <option value="critical">Critical</option>
                    <option value="high">High</option>
                    <option value="medium">Medium</option>
                    <option value="low">Low</option>
                  </select>
                </div>
                <div>
                  <label className="text-xs font-medium text-muted-foreground">Category</label>
                  <select value={form.category} onChange={e => setForm(f => ({...f, category: e.target.value}))}
                    className="mt-1 w-full h-9 rounded-lg border border-border bg-background px-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/40">
                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-medium text-muted-foreground">Assignee</label>
                  <Input value={form.assignee} onChange={e => setForm(f => ({...f, assignee: e.target.value}))}
                    placeholder="email@org.com" className="mt-1 h-9" />
                </div>
              </div>
              <div>
                <label className="text-xs font-medium text-muted-foreground">Tags (comma separated)</label>
                <Input value={form.tags} onChange={e => setForm(f => ({...f, tags: e.target.value}))}
                  placeholder="ransomware, finance, lateral-movement" className="mt-1" />
              </div>
              <div>
                <label className="text-xs font-medium text-muted-foreground">IOCs (one per line)</label>
                <textarea value={form.iocs} onChange={e => setForm(f => ({...f, iocs: e.target.value}))}
                  placeholder={"192.168.1.104\nmalicious-domain.com\nsha256:abc123…"}
                  rows={3} className="mt-1 w-full rounded-lg border border-border bg-background px-3 py-2 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-primary/40" />
              </div>
            </CardContent>
            <div className="border-t border-border/60 px-6 py-4 flex gap-3 justify-end">
              <Button variant="outline" onClick={() => { setShowForm(false); setForm(EMPTY); }}>Cancel</Button>
              <Button onClick={createIncident} disabled={!form.title.trim()}>Create Incident</Button>
            </div>
          </Card>
        </div>
      )}
    </div>
  );
}
